<?php
namespace App\Http\Controllers\Dashboard;
use App\Http\Controllers\Controller; use App\Http\Controllers\Dashboard\Concerns\RedirectsAfterSave; use Illuminate\Http\Request;
class TravelController extends Controller { use RedirectsAfterSave; public function edit(Request $request) { $registration=$request->user()->registrations()->with('travelInfo')->latest()->firstOrFail(); return view('dashboard.travel', compact('registration')); } public function update(Request $request) { $registration=$request->user()->registrations()->latest()->firstOrFail(); $data=$request->validate(['outbound_flight_number'=>['nullable','string'],'outbound_departure_airport'=>['nullable','string'],'outbound_departure_at'=>['nullable','date'],'outbound_arrival_airport'=>['nullable','string'],'outbound_arrival_at'=>['nullable','date'],'return_flight_number'=>['nullable','string'],'return_departure_airport'=>['nullable','string'],'return_departure_at'=>['nullable','date'],'return_arrival_airport'=>['nullable','string'],'return_arrival_at'=>['nullable','date'],'hotel_room_number'=>['nullable','string'],'bus_group'=>['nullable','string'],'notes'=>['nullable','string'],'return_to'=>['nullable','url']]); $returnTo=$data['return_to']??null; unset($data['return_to']); $registration->travelInfo()->updateOrCreate(['registration_id'=>$registration->id],$data); if ($returnTo) $request->merge(['return_to'=>$returnTo]); return $this->redirectAfterSave($request,'Travel saved'); } }
